import{questionMarkup}from'./question-cues.js';
import{guardianPhase}from'./guardian-combat.js';
import{icon}from'./ui-icons.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function guardianMessage(b){if(b.phase==='intro')return'The guardian awakens…';if(b.phase==='finisher')return'Break the final three seals · correct answers stay';if(b.phase==='victory')return'The guardian yields. Arena restored.';if(b.phase==='recovery')return'Core exposed · move within range and cast!';return{quake:'Shockwave · jump as the ring reaches you',beam:'Aimed strike · move sideways out of the marked lane',falls:'Falling stones · leave the marked circles'}[b.kind];}
export function guardianHud(b,name){return `<div class="guardian-hud"><div class="guardian-heading"><span>${esc(name)}</span><button data-do="retreat" aria-label="Save and return to sanctuary">${icon('close')}</button></div><div class="boss-health" role="meter" aria-label="Guardian health" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${b.bossHp}"><i style="width:${b.bossHp}%"></i></div><div class="guardian-health-note"><span>${b.bossHp}% · Phase ${guardianPhase(b)}</span><span>Your strength <b>${b.hp}</b></span></div><p id="guardian-callout" role="status">${guardianMessage(b)}</p></div>`;}
export function guardianFinisher(b,feedback=''){const q=b.seals[b.finishStep];if(!q)return'';return `<div class="guardian-finisher" aria-label="Final English seals"><div class="seal-count" aria-label="${b.finishStep} of three seals broken">${[0,1,2].map(i=>`<span class="${i<b.finishStep?'broken':''}">${i<b.finishStep?'✓':i+1}</span>`).join('')}</div><div class="finisher-question">${q.kind==='meaning'?`<span class="finisher-instruction">Connect its Turkish meaning</span>${esc(q.prompt)}`:q.kind==='completion'?`<span class="finisher-instruction">Complete the inscription</span>${esc(q.prompt)}`:questionMarkup(q.prompt)}</div><div class="finisher-answers">${q.options.map((s,i)=>`<button type="button" data-do="guardian-answer" data-index="${i}" data-step="${b.finishStep}"><span class="seal-symbol" aria-hidden="true">◇</span><span>${esc(s)}</span></button>`).join('')}</div><p class="finisher-feedback" role="status">${esc(feedback||'Read, then touch a rune. No reading timer.')}</p></div>`;}
export function guardianControls(){return `<div class="play-dock guardian-dock"><div class="joystick" id="joystick" aria-label="Move your creature"><div id="joystick-thumb"></div></div><button class="attack-button" id="attack-button" data-do="attack" aria-label="Cast your elemental attack">${icon('attack')}<small>Cast</small></button><button class="jump-button" id="jump-button" data-do="jump" aria-label="Jump over a shockwave">${icon('jump')}<small>Jump</small></button><div class="guardian-keyboard">WASD / arrows · Space jump · J / F cast</div></div>`;}
